27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public String getPostcode() {
111	        return this.postcode;
112	    }
113	
114	    public void setPostcode(String postcode) {
115	        this.postcode = postcode;
116	    }
117	
118	    public LocalDate getRegistrationDate() {
119	        return this.registrationDate;
120	    }
121	
122	    public void setRegistrationDate(LocalDate registrationDate) {
123	        this.registrationDate = registrationDate;
124	    }
125	
126	    public String getCustomerCode() {
127	        return this.customerCode;
128	    }
129	
130	    public void setCustomerCode(String customerCode) {
131	        this.customerCode = customerCode;
132	    }
133	
134	    public String getHouseholdId() {
135	        return this.householdId;
136	    }
137	
138	    public void setHouseholdId(String householdId) {
139	        this.householdId = householdId;
140	    }
141	
142	    public Integer getNamesakeCount() {
143	        return this.namesakeCount;
144	    }
145	
146	    public void setNamesakeCount(Integer namesakeCount) {
147	        this.namesakeCount = namesakeCount;
148	    }
149	
150	    /**
151	     * Whether more than 80 owners had already been created today at the time this owner
152	     * was created, indicating an unusually high signup volume.
153	     *
154	     * @return {@code true} when the bulk-signup threshold was exceeded, otherwise
155	     *         {@code false} (never {@code null})
156	     */
157	    public Boolean getBulkSignupWarning() {
158	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
159	    }
160	
161	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
162	        this.bulkSignupWarning = bulkSignupWarning;
163	    }
164	
165	    /**
166	     * The number of owners in this owner's household (owners sharing the same
167	     * {@code householdId}) as of when this owner was created, used to derive the GOLD
168	     * membership tier.
169	     *
170	     * @return the household member count, or {@code null} if it has not been assigned
171	     */
172	    public Integer getHouseholdSize() {
173	        return this.householdSize;
174	    }
175	
176	    public void setHouseholdSize(Integer householdSize) {
177	        this.householdSize = householdSize;
178	    }
179	
180	    /**
181	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
182	     *
183	     * @return the formatted display name
184	     */
185	    public String getDisplayName() {
186	        return this.getLastName() + ", " + this.getFirstName();
187	    }
188	
189	    /**
190	     * The owner's initials: the upper-cased first letters of the first and last
191	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
192	     *
193	     * @return the formatted initials
194	     */
195	    public String getInitials() {
196	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
197	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
198	    }
199	
200	    /**
201	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
202	     * {@code YY} is the last two digits of the registration date's year (e.g.
203	     * {@code "SYD-SMI-0007-M26"}).
204	     *
205	     * @return the formatted membership number, or {@code null} if the customer code or
206	     *         registration date has not been assigned
207	     */
208	    public String getMembershipNumber() {
209	        if (this.customerCode == null || this.registrationDate == null) {
210	            return null;
211	        }
212	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
213	    }
214	
215	    /**
216	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
217	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
218	     * (non-digit characters are ignored).
219	     *
220	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
221	     */
222	    public Integer getCheckDigit() {
223	        if (this.customerCode == null) {
224	            return null;
225	        }
226	        int sum = 0;
227	        boolean dbl = true;
228	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
229	            char c = this.customerCode.charAt(i);
230	            if (c < '0' || c > '9') {
231	                continue;
232	            }
233	            int d = c - '0';
234	            if (dbl) {
235	                d *= 2;
236	                if (d > 9) {
237	                    d -= 9;
238	                }
239	            }
240	            sum += d;
241	            dbl = !dbl;
242	        }
243	        return (10 - (sum % 10)) % 10;
244	    }
245	
246	    /**
247	     * The owner's numeric membership level, from {@code 1} to {@code 3}, computed on
248	     * creation. It starts at {@code 1}, gains {@code 1} when this owner carries an email
249	     * address, gains {@code 1} when this owner has no namesakes ({@code namesakeCount} is
250	     * {@code 0}), and is capped at {@code 3} (level {@code 4} is reserved for tenure).
251	     *
252	     * @return the membership level
253	     */
254	    public Integer getMembershipLevel() {
255	        int level = 1;
256	        boolean hasEmail = this.email != null && !this.email.isBlank();
257	        if (hasEmail) {
258	            level++;
259	        }
260	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
261	        if (noNamesakes) {
262	            level++;
263	        }
264	        return Math.min(level, 3);
265	    }
266	
267	    /**
268	     * The owner's preferred contact channel: {@code "EMAIL"} when the owner carries an
269	     * email address, otherwise {@code "PHONE"}.
270	     *
271	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
272	     */
273	    public String getContactPreference() {
274	        boolean hasEmail = this.email != null && !this.email.isBlank();
275	        return hasEmail ? "EMAIL" : "PHONE";
276	    }
277	
278	    /**
279	     * The owner's identity key: the single derived value used for duplicate detection, formed as
280	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
281	     * email are the already-normalized stored values and a {@code null} email or household id is
282	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
283	     * are equal; because the telephone is part of the key, household members with different
284	     * telephones have different identity keys.
285	     *
286	     * @return the derived identity key
287	     */
288	    public String getIdentityKey() {
289	        String telephonePart = this.telephone == null ? "" : this.telephone;
290	        String emailPart = this.email == null ? "" : this.email;
291	        String householdPart = this.householdId == null ? "" : this.householdId;
292	        return telephonePart + "|" + emailPart + "|" + householdPart;
293	    }
294	
295	    /**
296	     * City -> canonical region, the fixed ground truth for deriving locality.
297	     */
298	    private static final Map<String, String> CITY_REGION = Map.of(
299	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
300	
301	    /**
302	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
303	     * deriving locality from the postcode ahead of the city.
304	     */
305	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
306	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
307	
308	    /**
309	     * The owner's locality: the canonical region resolved by the postcode range first
310	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
311	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
312	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
313	     * when the city is not in the table either. The postcode takes precedence so cities that share a
314	     * name are disambiguated by their postcode's region.
315	     *
316	     * @return the canonical region string, or {@code "UNKNOWN"}
317	     */
318	    public String getLocality() {
319	        String byPostcode = regionForPostcode(this.postcode);
320	        if (byPostcode != null) {
321	            return byPostcode;
322	        }
323	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
324	    }
325	
326	    /**
327	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
328	     * absent, not a 4-digit number, or in no known range.
329	     *
330	     * @param postcode the owner's postcode (may be {@code null})
331	     * @return the matching region, or {@code null}
332	     */
333	    private static String regionForPostcode(String postcode) {
334	        if (postcode == null || !postcode.matches("\\d{4}")) {
335	            return null;
336	        }
337	        int value = Integer.parseInt(postcode);
338	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
339	            int[] range = entry.getValue();
340	            if (value >= range[0] && value <= range[1]) {
341	                return entry.getKey();
342	            }
343	        }
344	        return null;
345	    }
346	
347	    protected Set<Pet> getPetsInternal() {
348	        if (this.pets == null) {
349	            this.pets = new HashSet<>();
350	        }
351	        return this.pets;
352	    }
353	
354	    protected void setPetsInternal(Set<Pet> pets) {
355	        this.pets = pets;
356	    }
357	
358	    public List<Pet> getPets() {
359	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
360	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
361	        return Collections.unmodifiableList(sortedPets);
362	    }
363	
364	    public void setPets(List<Pet> pets) {
365	        this.pets = new HashSet<>(pets);
366	    }
367	
368	    public void addPet(Pet pet) {
369	        getPetsInternal().add(pet);
370	        pet.setOwner(this);
371	    }
372	
373	    /**
374	     * Return the Pet with the given name, or null if none found for this Owner.
375	     *
376	     * @param name to test
377	     * @return true if pet name is already in use
378	     */
379	    public Pet getPet(String name) {
380	        return getPet(name, false);
381	    }
382	
383	    /**
384	     * Return the Pet with the given name, or null if none found for this Owner.
385	     *
386	     * @param name to test
387	     * @return true if pet name is already in use
388	     */
389	    public Pet getPet(String name, boolean ignoreNew) {
390	        name = name.toLowerCase();
391	        for (Pet pet : getPetsInternal()) {
392	            if (!ignoreNew || !pet.isNew()) {
393	                String compName = pet.getName();
394	                compName = compName.toLowerCase();
395	                if (compName.equals(name)) {
396	                    return pet;
397	                }
398	            }
399	        }
400	        return null;
401	    }
402	
403	    public Pet getPet(Integer petId) {
404	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
405	    }
406	
407	    @Override
408	    public String toString() {
409	        return new ToStringCreator(this)
410	
411	            .append("id", this.getId())
412	            .append("new", this.isNew())
413	            .append("lastName", this.getLastName())
414	            .append("firstName", this.getFirstName())
415	            .append("address", this.address)
416	            .append("city", this.city)
417	            .append("telephone", this.telephone)
418	            .append("email", this.email)
419	            .toString();
420	    }
421	}
