36	import org.springframework.samples.petclinic.mapper.OwnerMapper;
37	import org.springframework.samples.petclinic.mapper.PetMapper;
38	import org.springframework.samples.petclinic.mapper.VisitMapper;
39	import org.springframework.samples.petclinic.model.Owner;
40	import org.springframework.samples.petclinic.model.Pet;
41	import org.springframework.samples.petclinic.model.Visit;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /**
68	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
69	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
70	     */
71	    /**
72	     * Dedicated audit logger. Successful side-effects (e.g. owner creation) are recorded here so
73	     * they can be routed and asserted independently of the application's diagnostic logging.
74	     */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    private static final Pattern EMAIL_PATTERN =
78	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
79	
80	    /**
81	     * Common address abbreviations expanded to their full form during address normalization.
82	     * Matching is performed per whitespace-separated token on the upper-cased value.
83	     */
84	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
85	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
86	
87	    /**
88	     * Required national-number length (the digits after the country code) per E.164 country code.
89	     * A number whose country code appears here must carry exactly the mapped number of national
90	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
91	     */
92	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
93	        Map.of("61", 9, "1", 10);
94	
95	    /**
96	     * Inclusive 4-digit postcode range {@code {low, high}} per region, the fixed ground truth for
97	     * validating an owner's postcode against the region derived from its city. A region not listed
98	     * here (e.g. the {@code "UNKNOWN"} locality of an unmapped city) imposes no range constraint, so
99	     * any 4-digit postcode is accepted.
100	     */
101	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
102	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
103	
104	    private final ClinicService clinicService;
105	
106	    private final OwnerMapper ownerMapper;
107	
108	    private final PetMapper petMapper;
109	
110	    private final VisitMapper visitMapper;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper) {
116	        this.clinicService = clinicService;
117	        this.ownerMapper = ownerMapper;
118	        this.petMapper = petMapper;
119	        this.visitMapper = visitMapper;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        HttpHeaders headers = new HttpHeaders();
151	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
152	        LocalDate effectiveDate = owner.getRegistrationDate() != null
153	            ? owner.getRegistrationDate() : LocalDate.now();
154	        LocalDate registrationDate = toBusinessDay(effectiveDate);
155	        owner.setRegistrationDate(registrationDate);
156	        long createdToday = this.clinicService.findAllOwners().stream()
157	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
158	            .count();
159	        if (createdToday >= 100) {
160	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
161	        }
162	        owner.setBulkSignupWarning(createdToday > 80);
163	        String address = normalizeAddress(owner.getAddress());
164	        if (address == null || address.isEmpty()) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        owner.setAddress(address);
168	        String telephone = toE164(owner.getTelephone());
169	        if (telephone == null) {
170	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	        }
172	        owner.setTelephone(telephone);
173	        if (owner.getEmail() != null) {
174	            String email = normalizeEmail(owner.getEmail());
175	            if (!EMAIL_PATTERN.matcher(email).matches()) {
176	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
177	            }
178	            owner.setEmail(email);
179	        }
180	        if (!isPostcodeValidForCity(owner.getPostcode(), owner.getLocality())) {
181	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
182	        }
183	        String cityKey = householdKey(owner.getCity());
184	        long cityCount = this.clinicService.findAllOwners().stream()
185	            .filter(existing -> existing.getCity() != null
186	                && cityKey.equals(householdKey(existing.getCity())))
187	            .count();
188	        if (cityCount >= 50) {
189	            return new ResponseEntity<>(HttpStatus.CONFLICT);
190	        }
191	        String lastNameKey = householdKey(owner.getLastName());
192	        String addressKey = householdKey(owner.getAddress());
193	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
194	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
195	                && addressKey.equals(householdKey(existing.getAddress())))
196	            .toList();
197	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
198	        if (sharesHousehold) {
199	            String householdId = householdMembers.stream()
200	                .map(Owner::getHouseholdId)
201	                .filter(Objects::nonNull)
202	                .findFirst()
203	                .orElseGet(() -> householdId(owner));
204	            owner.setHouseholdId(householdId);
205	            owner.setHouseholdSize(householdMembers.size() + 1);
206	        } else {
207	            owner.setHouseholdSize(1);
208	        }
209	        // Single consolidated duplicate check: the telephone, email and household duplicate rules are
210	        // all expressed through the one derived identityKey (telephone|email|householdId). A create is
211	        // rejected only when a new owner's WHOLE identityKey equals an existing owner's; because the
212	        // telephone is part of the key, two household members with different telephones are allowed.
213	        String identityKey = owner.getIdentityKey();
214	        boolean identityInUse = this.clinicService.findAllOwners().stream()
215	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
216	        if (identityInUse) {
217	            return new ResponseEntity<>(HttpStatus.CONFLICT);
218	        }
219	        if (sharesHousehold) {
220	            for (Owner member : householdMembers) {
221	                if (member.getHouseholdId() == null) {
222	                    member.setHouseholdId(owner.getHouseholdId());
223	                    this.clinicService.saveOwner(member);
224	                }
225	            }
226	        }
227	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
228	        String firstNameKey = householdKey(owner.getFirstName());
229	        String namesakeLastNameKey = householdKey(owner.getLastName());
230	        long namesakeCount = this.clinicService.findAllOwners().stream()
231	            .filter(existing -> firstNameKey.equals(householdKey(existing.getFirstName()))
232	                && namesakeLastNameKey.equals(householdKey(existing.getLastName())))
233	            .count();
234	        owner.setNamesakeCount((int) namesakeCount);
235	        this.clinicService.saveOwner(owner);
236	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
237	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
238	            owner.getMembershipLevel());
239	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
240	        headers.setLocation(UriComponentsBuilder.newInstance()
241	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
242	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    /**
246	     * Validates an owner's postcode against the region derived from its city. The postcode is
247	     * optional: a {@code null} value is always accepted. When present it must fall within the
248	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
249	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
250	     * The 4-digit syntax itself is enforced upstream by bean validation.
251	     *
252	     * @param postcode the owner's postcode (may be {@code null})
253	     * @param locality the region derived from the owner's city
254	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
255	     *         within the region's range; {@code false} when it is out of range
256	     */
257	    private boolean isPostcodeValidForCity(String postcode, String locality) {
258	        if (postcode == null) {
259	            return true;
260	        }
261	        int[] range = REGION_POSTCODES.get(locality);
262	        if (range == null) {
263	            return true;
264	        }
265	        int value = Integer.parseInt(postcode);
266	        return value >= range[0] && value <= range[1];
267	    }
268	
269	    /**
270	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
271	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
272	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
273	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. For
274	     * recognised country codes the national number (the digits after the country code) must also be
275	     * exactly the length that country requires ({@code '+61'} needs 9 national digits, {@code '+1'}
276	     * needs 10); a wrong national-number length yields {@code null}.
277	     *
278	     * @param telephone the raw telephone value (may be {@code null})
279	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
280	     *         a valid E.164 number
281	     */
282	    private String toE164(String telephone) {
283	        if (telephone == null) {
284	            return null;
285	        }
286	        String trimmed = telephone.trim();
287	        boolean hasCountryCode = trimmed.startsWith("+");
288	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
289	        if (hasCountryCode) {
290	            cleaned = cleaned.substring(1);
291	        }
292	        if (!cleaned.matches("[0-9]+")) {
293	            return null;
294	        }
295	        String digits;
296	        if (hasCountryCode) {
297	            digits = cleaned;
298	        } else {
299	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
300	            digits = "61" + national;
301	        }
302	        if (digits.length() < 8 || digits.length() > 15) {
303	            return null;
304	        }
305	        if (!hasValidNationalNumberLength(digits)) {
306	            return null;
307	        }
308	        return "+" + digits;
309	    }
310	
311	    /**
312	     * Checks the national-number length of an E.164 digit string (country code plus national
313	     * number, without the leading {@code '+'}) against its country code. When the number's country
314	     * code is one of the {@link #NATIONAL_NUMBER_LENGTHS recognised codes}, the digits after the
315	     * country code must number exactly what that country requires; the longest matching country
316	     * code wins. Numbers whose country code is not recognised are accepted here (they are governed
317	     * only by the generic total-length rule).
318	     *
319	     * @param digits the E.164 digits without the leading {@code '+'} (e.g. {@code "61412345678"})
320	     * @return {@code true} if the national-number length is acceptable for the country code
321	     */
322	    private boolean hasValidNationalNumberLength(String digits) {
323	        return NATIONAL_NUMBER_LENGTHS.entrySet().stream()
324	            .filter(entry -> digits.startsWith(entry.getKey()))
325	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
326	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
327	            .orElse(true);
328	    }
329	
330	    /**
331	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
332	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
333	     *
334	     * @param email the raw email value (must not be {@code null})
335	     * @return the trimmed, lower-cased email
336	     */
337	    private String normalizeEmail(String email) {
338	        return email.trim().toLowerCase(Locale.ROOT);
339	    }
340	
341	    /**
342	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
343	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
344	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
345	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
346	     * normalized form, and every household comparison uses it.
347	     *
348	     * @param address the raw address value (may be {@code null})
349	     * @return the normalized address, or {@code null} if the input was {@code null}
350	     */
351	    private String normalizeAddress(String address) {
352	        if (address == null) {
353	            return null;
354	        }
355	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
356	        if (collapsed.isEmpty()) {
357	            return collapsed;
358	        }
359	        String[] tokens = collapsed.split(" ");
360	        StringBuilder sb = new StringBuilder(collapsed.length());
361	        for (int i = 0; i < tokens.length; i++) {
362	            if (i > 0) {
363	                sb.append(' ');
364	            }
365	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
366	        }
367	        return sb.toString();
368	    }
369	
370	    /**
371	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
372	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
373	     * so that owners are compared case-insensitively with collapsed whitespace.
374	     *
375	     * @param value the raw value (must not be {@code null})
376	     * @return the normalized comparison key
377	     */
378	    private String householdKey(String value) {
379	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
380	    }
381	
382	    /**
383	     * Derives a stable, shared household identifier for the owner's household. The value is a
384	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
385	     * every owner in the same household derives the identical identifier of the form
386	     * {@code 'HH-<12 upper-case hex>'}.
387	     *
388	     * @param owner the owner whose household identifier is derived
389	     * @return the stable household identifier
390	     */
391	    private String householdId(Owner owner) {
392	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
393	        try {
394	            byte[] digest = MessageDigest.getInstance("SHA-256")
395	                .digest(key.getBytes(StandardCharsets.UTF_8));
396	            StringBuilder sb = new StringBuilder(digest.length * 2);
397	            for (byte b : digest) {
398	                sb.append(String.format("%02x", b));
399	            }
400	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
401	        }
402	        catch (java.security.NoSuchAlgorithmException e) {
403	            throw new IllegalStateException("SHA-256 not available", e);
404	        }
405	    }
406	
407	    /**
408	     * Builds the customer code for a newly registered owner in the form
409	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three
410	     * letters of the city, {@code LAST3} the upper-cased first three letters of the last name
411	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
412	     * number of owners already registered in that city (e.g. {@code 'SYD-SMI-0007'}).
413	     *
414	     * @param city     the owner's city
415	     * @param lastName the owner's last name
416	     * @return the assigned customer code
417	     */
418	    private String nextCustomerCode(String city, String lastName) {
419	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
420	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
421	        String cityKey = householdKey(city);
422	        int sequence = (int) this.clinicService.findAllOwners().stream()
423	            .filter(existing -> existing.getCity() != null && cityKey.equals(householdKey(existing.getCity())))
424	            .count() + 1;
425	        return String.format(Locale.ROOT, "%s-%s-%04d", city3, last3, sequence);
426	    }
427	
428	    /**
429	     * Rolls a registration date forward onto a business day. When the given date falls on a
430	     * Saturday or Sunday it is advanced to the following Monday; a weekday is returned unchanged.
431	     *
432	     * @param date the effective registration date (must not be {@code null})
433	     * @return the same date if it is a weekday, otherwise the next Monday
434	     */
435	    private LocalDate toBusinessDay(LocalDate date) {
436	        DayOfWeek dayOfWeek = date.getDayOfWeek();
437	        if (dayOfWeek == DayOfWeek.SATURDAY) {
438	            return date.plusDays(2);
439	        }
440	        if (dayOfWeek == DayOfWeek.SUNDAY) {
441	            return date.plusDays(1);
442	        }
443	        return date;
444	    }
445	
446	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
447	    @Override
448	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
449	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
450	        if (currentOwner == null) {
451	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
452	        }
453	        String email = ownerFieldsDto.getEmail();
454	        if (email != null) {
455	            email = normalizeEmail(email);
456	            if (!EMAIL_PATTERN.matcher(email).matches()) {
457	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
458	            }
459	        }
460	        String telephone = toE164(ownerFieldsDto.getTelephone());
461	        if (telephone == null) {
462	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
463	        }
464	        currentOwner.setAddress(ownerFieldsDto.getAddress());
465	        currentOwner.setCity(ownerFieldsDto.getCity());
466	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
467	        currentOwner.setLastName(ownerFieldsDto.getLastName());
468	        currentOwner.setTelephone(telephone);
469	        currentOwner.setEmail(email);
470	        this.clinicService.saveOwner(currentOwner);
471	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
472	    }
473	
474	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
475	    @Transactional
476	    @Override
477	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
478	        Owner owner = this.clinicService.findOwnerById(ownerId);
479	        if (owner == null) {
480	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
481	        }
482	        this.clinicService.deleteOwner(owner);
483	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
484	    }
485	
486	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
487	    @Override
488	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
489	        Owner owner = this.clinicService.findOwnerById(ownerId);
490	        if (owner == null) {
491	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
492	        }
493	        HttpHeaders headers = new HttpHeaders();
494	        Pet pet = petMapper.toPet(petFieldsDto);
495	        owner.setId(ownerId);
496	        pet.setOwner(owner);
497	        pet.getType().setName(null);
498	        this.clinicService.savePet(pet);
499	        PetDto petDto = petMapper.toPetDto(pet);
500	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
501	            .buildAndExpand(pet.getId()).toUri());
502	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
503	    }
504	
505	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
506	    @Override
507	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
508	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
509	        if (currentOwner != null) {
510	            Pet currentPet = this.clinicService.findPetById(petId);
511	            if (currentPet != null) {
512	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
513	                currentPet.setName(petFieldsDto.getName());
514	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
515	                this.clinicService.savePet(currentPet);
516	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
517	            }
518	        }
519	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
520	    }
521	
522	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
523	    @Override
524	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
525	        HttpHeaders headers = new HttpHeaders();
526	        Visit visit = visitMapper.toVisit(visitFieldsDto);
527	        Pet pet = new Pet();
528	        pet.setId(petId);
529	        visit.setPet(pet);
530	        this.clinicService.saveVisit(visit);
531	        VisitDto visitDto = visitMapper.toVisitDto(visit);
532	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
533	            .buildAndExpand(visit.getId()).toUri());
534	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
535	    }
536	
537	
538	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
539	    @Override
540	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
541	        Owner owner = this.clinicService.findOwnerById(ownerId);
542	        if (owner != null) {
543	            Pet pet = owner.getPet(petId);
544	            if (pet != null) {
545	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
546	            }
547	        }
548	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
549	    }
550	}
